CREATE TABLE `T_CK_SVC_WORKFLOW` (
  `WKFL_ID` varchar(35) NOT NULL COMMENT 'WORK FLOW ID - UUID',
  `WKFL_APPS_CODE` varchar(35) NOT NULL COMMENT 'APPS CODES - REFERENCES T_CORE_APPS:APPS_CODE',
  `WKFL_ROLE` varchar(35) NOT NULL COMMENT 'ROLE - REFERENCES T_CORE_ROLE:ROLE_APPSCODE,ROLE_ID',
  `WKFL_SCV_TYPE` varchar(35) NOT NULL COMMENT 'SERVICE TYPE - REFERENCES T_CK_MST_SERVICE_TYPE:SVCT_ID',
  `WKFL_ACTION` varchar(35) NOT NULL COMMENT 'ACTION TYPE - REFERENCES T_CK_MST_ACTION:ACT_ID',
  `WKFL_FROM_STATE` varchar(35) NOT NULL COMMENT 'FROM JOB STATE - REFERENCES T_CK_MST_JOB_STATE:JBST_ID',
  `WKFL_TO_STATE` varchar(35) NOT NULL COMMENT 'TO JOB STATE - REFERENCES T_CK_MST_JOB_STATE:JBST_ID',
  `WKFL_URI` varchar(255) DEFAULT NULL COMMENT 'URI TO TRIGGER THE ACTION',
  `WKFL_STATUS` char(1) NOT NULL,
  `WKFL_DT_CREATE` datetime DEFAULT NULL,
  `WKFL_UID_CREATE` varchar(35) DEFAULT NULL,
  `WKFL_DT_LUPD` datetime DEFAULT NULL,
  `WKFL_UID_LUPD` varchar(35) DEFAULT NULL,
  PRIMARY KEY (`WKFL_ID`),
  CONSTRAINT `FK_CK_SVC_WORKFLOW_CORE_APPS` FOREIGN KEY (`WKFL_APPS_CODE`) REFERENCES `T_CORE_APPS` (`APPS_CODE`),
  CONSTRAINT `FK_CK_SVC_WORKFLOW_CORE_ROLE` FOREIGN KEY (`WKFL_APPS_CODE`, `WKFL_ROLE`) REFERENCES `T_CORE_ROLE` (`ROLE_APPSCODE`,`ROLE_ID`),
  CONSTRAINT `FK_CK_SVC_WORKFLOW_CK_MST_SERVICE_TYPE` FOREIGN KEY (`WKFL_SCV_TYPE`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_SVC_WORKFLOW_CK_MST_ACTION` FOREIGN KEY (`WKFL_ACTION`) REFERENCES `T_CK_MST_FORM_ACTION` (`FMACT_ID`),
  CONSTRAINT `FK_CK_SVC_WORKFLOW_CK_MST_JOB_STATE1` FOREIGN KEY (`WKFL_FROM_STATE`) REFERENCES `T_CK_MST_JOB_STATE` (`JBST_ID`),
  CONSTRAINT `FK_CK_SVC_WORKFLOW_CK_MST_JOB_STATE2` FOREIGN KEY (`WKFL_TO_STATE`) REFERENCES `T_CK_MST_JOB_STATE` (`JBST_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT 'SERVICE WORKFLOW TABLE';



