  `VH_LENGTH` smallint DEFAULT '0' COMMENT 'VEHICLE LENGTH IN METERS',
  `VH_WIDTH` smallint DEFAULT '0' COMMENT 'VEHICLE WIDTH IN METERS',
  `VH_HEIGHT` smallint DEFAULT '0' COMMENT 'VEHICLE HEIGHT IN METERS',
  `VH_WEIGHT` mediumint DEFAULT '0' COMMENT 'VEHICLE WEIGHT IN KG',
  `VH_VOLUME` mediumint DEFAULT '0' COMMENT 'VEHICLE VOLUME IN CUBIC METER',
  `VH_CHASSIS_TYPE` varchar(35) DEFAULT NULL COMMENT 'VEHICLE CHASSIS TYPE - REFERENCES T_CK_CT_MST_CHASSIS_TYPE:CHTY_ID',
  `VH_CHASSIS_NO` varchar(256) DEFAULT NULL COMMENT 'VEHICLE CHASSIS NUMBER',
  `VH_IS_MAINTENANCE` char(1) DEFAULT 'N' COMMENT 'VEHICLE IS UNDER MAINTENANCE - Y:N',
