  `VH_STATUS` char(1) DEFAULT NULL COMMENT 'VEHICLE STATE STATUS',
  `VH_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `VH_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `VH_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `VH_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`VH_ID`),
  KEY `FK_CK_CT_VEH_CK_CT_MST_VEH_TYPE` (`VH_TYPE`),
  KEY `FK_CK_CT_VEH_CK_CT_MST_VEH_STATE` (`VH_STATE`),
