  KEY `FK_CK_CT_VEH_CK_CT_MST_CHASSIS_TYPE` (`VH_CHASSIS_TYPE`),
  CONSTRAINT `FK_CK_CT_VEH_CK_CT_MST_CHASSIS_TYPE` FOREIGN KEY (`VH_CHASSIS_TYPE`) REFERENCES `T_CK_CT_MST_CHASSIS_TYPE` (`CHTY_ID`),
  CONSTRAINT `FK_CK_CT_VEH_CK_CT_MST_VEH_STATE` FOREIGN KEY (`VH_STATE`) REFERENCES `T_CK_CT_MST_VEH_STATE` (`VHST_ID`),
  CONSTRAINT `FK_CK_CT_VEH_CK_CT_MST_VEH_TYPE` FOREIGN KEY (`VH_TYPE`) REFERENCES `T_CK_CT_MST_VEH_TYPE` (`VHTY_ID`),
  CONSTRAINT `FK_CK_CT_VEH_CORE_ACCN` FOREIGN KEY (`VH_COMPANY`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='VEHICLE TABLE';
